insert into public.public_content (id, kind, status, data)
select seed.id, seed.kind, seed.status, seed.data
from jsonb_to_recordset($content$
[
  {"id":"homepage","kind":"homepage","status":"Published","data":{"headline":"Learn digital skills. Get mentored. Build your career.","announcement":"","bannerUrl":"","contactEmail":"hello@skill-up.ng","privacyPolicy":"","terms":""}},
  {"id":"faq:FAQ-01","kind":"faq","status":"Published","data":{"id":"FAQ-01","question":"How do I get started?","answer":"Explore the courses, choose a skill that matches your goals and follow the enrolment steps to begin learning.","status":"Published"}},
  {"id":"faq:FAQ-02","kind":"faq","status":"Published","data":{"id":"FAQ-02","question":"Do I need previous experience?","answer":"Many of our courses can accommodate beginners. Check the individual course requirements before enrolling.","status":"Published"}},
  {"id":"faq:FAQ-03","kind":"faq","status":"Published","data":{"id":"FAQ-03","question":"Will I receive mentorship?","answer":"Mentorship and learning support are part of the SKILL-UP learning experience, according to the support arrangements for each programme.","status":"Published"}},
  {"id":"faq:FAQ-04","kind":"faq","status":"Published","data":{"id":"FAQ-04","question":"Can SKILL-UP help me secure remote jobs?","answer":"We provide career preparation and support for finding opportunities. Employment is not guaranteed.","status":"Published"}},
  {"id":"faq:FAQ-05","kind":"faq","status":"Published","data":{"id":"FAQ-05","question":"Can I learn with my phone?","answer":"You can access the platform using a supported smartphone, tablet or computer. Some practical exercises may be easier on a laptop.","status":"Published"}},
  {"id":"faq:FAQ-06","kind":"faq","status":"Published","data":{"id":"FAQ-06","question":"Will I receive a certificate?","answer":"Eligible learners can receive certificates after meeting the completion requirements of their courses.","status":"Published"}}
]
$content$::jsonb) as seed(id text, kind text, status text, data jsonb)
on conflict (id) do nothing;
